public static int findNthLeapYear(int Y, int N) {
    // Validate input parameters
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Years must be positive integers");
    }

    // Method to check if a year is a leap year
    boolean isLeapYear(int year) {
        return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    }

    // Helper function to find the Nth leap year
    public int getNextLeapYear(int year) {
        while (year <= Y + N - 1) {
            year++;
            if (isLeapYear(year)) {
                return year;
            }
        }
        throw new RuntimeException("Not enough leap years after the start year");
    }

    return getNextLeapYear(Y);
}
