import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PermuteAll {
    public List<List<Integer>> permute(int[] nums) {
        // Initialize the result list to hold the permutations
        List<List<Integer>> result = new ArrayList<>();
        // Helper function to rotate subarray from start to end
        void rotate(int[] arr, int start, int end) {
            while (start < end) {
                int temp = arr[start];
                arr[start] = arr[end];
                arr[end] = temp;
                start++;
                end--;
            }
        }
        // Backtracking function to generate permutations
        void backtrack(int[] arr, int start, List<List<Integer>> result) {
            // If start is equal to array length, add the current permutation to result
            if (start == arr.length) {
                result.add(new ArrayList<>(Arrays.stream(arr).boxed().collect(Collectors.toList())));
                return;
            }
            // For each element from start to the end, swap it with the current element
            for (int i = start; i < arr.length; i++) {
                swap(arr, start, i);
                // Recursively perform backtracking on the rest of the array
                backtrack(arr, start + 1, result);
                // Backtrack to unmake the swap (restore original array)
                swap(arr, start, i);
            }
        }
        // Swap two elements in the given indices
        void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
        // Start the permutation process
        backtrack(nums, 0, result);
        return result;
    }
}
