import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    backtrace(nums, 0, new ArrayList<>(), result);
    return result;
}

private void backtrace(int[] nums, int start, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        if (isUsed(nums, current, i)) {
            continue;
        }
        current.add(nums[i]);
        backtrace(nums, i + 1, current, result);
        current.remove(current.size() - 1);
    }
}

private boolean isUsed(int[] nums, List<Integer> current, int index) {
    for (int num : current) {
        if (num == nums[index]) {
            return true;
        }
    }
    return false;
}
