import java.util.*;
import java.util.stream.*;

public class StringAnalysis {

    public int findLargestSubstring(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            throw new IllegalArgumentException("Input list cannot be null or empty");
        }

        int maxLength = 0;

        for (int i = 0; i < strings.size(); i++) {
            String str = strings.get(i);
           maxLength = Math.max(maxLength, findMaxReversals(str) + 1);
        }

        return maxLength;
    }

    private int findMaxReversals(String str) {
        int index = str.indexOf(reverse(str));
        if (index == -1) {
            return str.length();
        }
        return str.lastIndexOf(str.substring(0, index)) + str.length() - index;
    }

    private String reverse(String str) {
        return new StringBuilder(str).reverse().toString();
    }

    public static void main(String[] args) {
        StringAnalysis solution = new StringAnalysis();
        List<String> examples = Arrays.asList("ABCD", "BCDFF", "BRCD");
        System.out.println(solution.findLargestSubstring(examples)); // Expected output: 2

        examples = Arrays.asList("rose", "orchid");
        System.out.println(solution.findLargestSubstring(examples)); // Expected output: 2
    }
}
