public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    int maxLength = 0;

    // Check each string and its reverse
    for (String str : strings) {
        String reversedStr = new StringBuilder(str).reverse().toString();
        for (int i = 0; i <= str.length(); i++) {
            for (int j = 0; j <= str.length() - i; j++) {
                int subStr = str.substring(j, j + i);
                if (subStr.equals(reversedStr.substring(0, subStr.length())) || 
                    subStr.equals(reversedStr.substring(reversedStr.length() - subStr.length(), reversedStr.length()))) {
                    maxLength = Math.max(maxLength, i);
                }
            }
        }
    }

    return maxLength > 0 ? maxLength : 0;
}
