    Set<String> substringSets = new HashSet<>();
    for (String str : strings) {
        for (int i = 0; i <= str.length() / 2; i++) {
            substringSets.add(str.substring(i));
            if (!str.contains(substringSets.last()))
                substringSets.remove(substringSets.last());
        }
    }

    int maxLen = 0;
    for (String str : substringSets) {
        maxLen = Math.max(maxLen, str.length());
    }

    return maxLen;
