public static int countOilDeposits(char[][] grid) {
    Set<List<Integer>> visited = new HashSet<>();
    int numRows = grid.length;
    int numCols = grid[0].length;

    for (int i = 0; i < numRows; i++) {
        for (int j = 0; j < numCols; j++) {
            if (grid[i][j] == '@' && !visited.contains(List.of(i, j))) {
                int count = dfs(grid, i, j, visited);
                if (count > 0) {
                    visited.add(List.of(i, j));
                }
            }
        }
    }

    return visited.size();
}

private static int dfs(char[][] grid, int r, int c, Set<List<Integer>> visited) {
    if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] != '@' || visited.contains(List.of(r, c))) {
        return 0;
    }
    visited.add(List.of(r, c));
    return 1 + dfs(grid, r+1, c, visited) + dfs(grid, r-1, c, visited) + dfs(grid, r, c+1, visited) + dfs(grid, r, c-1, visited);
}
