private static void visitDeposits(char[][] grid, int[][] visited, int x, int y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || visited[x][y] != 0 || grid[x][y] != '@') {
        return;
    }

    visited[x][y] = 1;

    visitDeposits(grid, visited, x - 1, y);
    visitDeposits(grid, visited, x + 1, y);
    visitDeposits(grid, visited, x, y - 1);
    visitDeposits(grid, visited, x, y + 1);
}
