public static int countOilDeposits(char[][] grid) {
    HashSet<Integer> oilDeposits = new HashSet<>();

    for (int i = 0; i < grid.length; i++) {
        char[] row = grid[i];
        for (int j = 0; j < row.length; j++) {
            if (row[j] == '@') {
                int position = i * row.length + j;
                if (!oilDeposits.contains(position)) {
                    oilDeposits.add(position);
                    countOilDeposits(row, position, oilDeposits);
                }
            }
        }
    }

    return oilDeposits.size();
}

private static void countOilDeposits(char[] row, int currentPosition, HashSet<Integer> oilDeposits) {
    if (currentPosition < 0 || currentPosition >= row.length || row[currentPosition] != '@') {
        return;
    }

    int rightIndex = currentPosition + 1;
    while (rightIndex < row.length && row[rightIndex] == '@') {
        rightIndex++;
    }

    if (rightIndex == row.length) {
        oilDeposits.add(currentPosition);
        return;
    }

    int leftIndex = currentPosition - 1;
    while (leftIndex >= 0 && row[leftIndex] == '@') {
        leftIndex--;
    }

    if (leftIndex == -1) {
        oilDeposits.add(currentPosition);
        return;
    }

    oilDeposits.add(currentPosition);

    if (rightIndex < row.length) {
        countOilDeposits(row, rightIndex, oilDeposits);
    }

    if (leftIndex >= 0) {
        countOilDeposits(row, leftIndex, oilDeposits);
    }
}
