        return;
    }

    grid[r][c] = '*'; // Mark as visited
    exploreOil(grid, r + 1, c, rows, cols);
    exploreOil(grid, r - 1, c, rows, cols);
    exploreOil(grid, r, c + 1, rows, cols);
    exploreOil(grid, r, c - 1, rows, cols);
