public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Edge case: if start and end are the same, return "can be travelled"
    if (Arrays.equals(start, end)) {
        return "can be travelled";
    }

    boolean[] visited = new boolean[n];
    Arrays.fill(visited, false);

    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        for (int i = 0; i < n; i++) {
            // Check if the next intersection can be reached
            if (isAdjacent(current, i, paths) && !visited[i]) {
                visited[i] = true;
                queue.offer(new int[]{i, current[1]});
            }
        }
    }

    return "cannot be travelled";
}

private static boolean isAdjacent(int[] current, int next, int[][] paths) {
    for (int[] path : paths) {
        if (path[0] == current[0] && path[1] == next) {
            return true;
        }
    }
    return false;
}
