    if (!isValidPosition(n, end)) {
        return "cannot be travelled";
    }

    // Track the number of steps needed to reach the end position
    int steps = 0;

    // Use a queue to simulate the breadth-first search
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Set a_visited array to keep track of visited positions
    boolean[][] visited = new boolean[n + 1][n + 1];
    visited[start[0]][start[1]] = true;

