        // Check if the current position matches the end position
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Explore next possible moves
        int[][] moves = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] move : moves) {
            int newX = current[0] + move[0];
            int newY = current[1] + move[1];

            // Check if the new position is valid
            if (isValidPosition(n, new int[]{newX, newY}) && !visited[newX][newY]) {
                queue.add(new int[]{newX, newY});
                visited[newX][newY] = true;
                steps++;
            }
        }
    }

    // If the end position was not reached within the bounds or valid moves, return "cannot be travelled"
    return "cannot be travelled";
