public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty() || word1.length() != word2.length()) {
        throw new IllegalArgumentException("Both words must be non-empty and of the same length.");
    }

    int commonLetters = 0;
    int sumOfLengths = word1.length() * word2.length();

    for (int i = 0; i < word1.length(); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }

    if (commonLetters == 0) {
        return "0";
    } else {
        Rational fraction = new Rational(commonLetters, sumOfLengths);
        return fraction.toString();
    }
}

static class Rational {
    private int numerator;
    private int denominator;

    public Rational(int numerator, int denominator) {
        this.numerator = numerator;
        this.denominator = denominator;
        reduce();
    }

    public String toString() {
        return numerator + "/" + denominator;
    }

    private void reduce() {
        int gcd = calculateGCD(numerator, denominator);
        numerator /= gcd;
        denominator /= gcd;
        if (denominator < 0) {
            numerator *= -1;
            denominator *= -1;
        }
    }

    private int calculateGCD(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return calculateGCD(b, a % b);
        }
    }
}
