        for (int i = 0; i < (int) (n * 0.1); i++) {
            trimmedSum += arr[i];
            trimmedSum += arr[n - 1 - i];
        }
        return (trimmedSum - max(trimmedSum)) / (n - 2 * (int) (n * 0.1))*(1e9 + 7)/1e9;
