    public double trimMean(int[] arr) {
        if (arr == null || arr.length == 0) {
            throw new IllegalArgumentException("Array must not be null or empty");
        }

        int start = (int) (arr.length * 0.05);
        int end = arr.length - start - 1;

        // Sort the array
        Arrays.sort(arr);

        // Calculate the sum of elements from skip to end
        double sum = 0;
        for (int i = start; i <= end; i++) {
            sum += arr[i];
        }

        // Calculate the mean
        double mean = sum / (end + 1 - start);
        return mean;
    }
}
