public boolean canArrange(int[] arr, int k) {
    // Edge case: if arr length is odd, it's impossible to pair up
    if (arr.length % 2 != 0) return false;

    // Use a HashMap to count remainders of each element when divided by k
    Map<Integer, Integer> remainderCount = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
    }

    // Check if the counts of remainders that sum up to k are even
    for (int remainder : remainderCount.keySet()) {
        int complement = k - remainder;
        if (complement != remainder) {
            if (!remainderCount.containsKey(complement) || remainderCount.get(complement) % 2 != 0) {
                return false;
            }
        } else {
            // Special case: ifremainder is zero, it's possible to pair up all elements
            if (remainder == 0 && remainderCount.get(remainder) % 2 != 0) {
                return false;
            }
        }
    }

    // Otherwise, it's possible to pair up all elements
    return true;
}
