        if remainderCount.get(0) % 2 != 0) {
            return false;
        }
    }

    // Handle pairs with same remainder
    for (int i = 1; i < k; i++) {
        if (remainderCount.containsValue(i) && remainderCount.containsValue(k - i)) {
            if (remainderCount.get(i) != remainderCount.get(k - i)) {
                return false;
            }
        }
    }

    return true;
}
