    int time = 0;
    for (int next : adjList.get(curr)) {
        if (next != parent) {
            time += dfs(next, adjList, hasApple, curr);
        }
    }
    // Only count the time if the current node has an apple or children with apples
    return time + (hasApple[curr] || time > 0 ? 1 : 0);
}
