public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int N = n;
    int[] parent = new int[N];
    int[] timer = new int[N];
    int[] minTimeToApple = new int[N];

    for (int[] edge : edges) {
        parent[edge[1]] = edge[0];
    }

    int numberOfApple = 0;
    for (int i = 0; i < N; i++) {
        if (hasApple[i]) {
            numberOfApple++;
        }
    }

    dfs(0, parent, 0, timer, minTimeToApple, hasApple, numberOfApple);

    int answer = 2 * timer[n]; // time to collect apples + time to return to the starting node

    for (int i = 0; i < N; i++) {
        answer += minTimeToApple[i];
    }

    return answer;
}

private void dfs(int cur, int[] parent, int last, int[] timer, int[] minTimeToApple, boolean[] hasApple, int numberOfApple) {
    // find the first position in the tree where the time to collect apples < current time
    int position = findPositionInTree(cur, parent, last, timer, minTimeToApple, hasApple, numberOfApple);
    if (position == cur) {
        return;
    }

    // set the time to collect apples for the first position in the tree
    if (hasApple[position]) {
        timer[position] = 0;
    } else {
        timer[position] = 1;
    }

    // recurse on the rest of the tree
    dfs(position, parent, cur, timer, minTimeToApple, hasApple, numberOfApple);

    // set the time to collect apples for the current position in the tree
    int time = timer[position] == 1 ? 0 : 1;
    if (hasApple[cur]) {
        minTimeToApple[cur] = time;
    } else {
        minTimeToApple[cur] = time + minTimeToApple[position];
    }
}

private int findPositionInTree(int cur, int[] parent, int last, int[] timer, int[] minTimeToApple, boolean[] hasApple, int numberOfApple) {
    // find the first position in the tree where the time to collect apples < current time
    for (int i = cur + 1; i < numberOfApple && timer[i] < timer[cur]; i++) {
        if (hasApple[i]) {
            return i;
        }
    }
    return cur;
}
