public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // handle base cases
    if (n <= 1 || edges == null || hasApple == null) return 0;

    // initialize parent and time arrays
    int time = 0;
    int parent[] = new int[n];
    Arrays.fill(parent, -1);
    parent[0] = -2; // initialize parent of node 0

    // build adjacency list representation of the tree
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        graph.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
        graph.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
    }

    // perform DFS to calculate the minimum time required to collect all apples and return to node 0
    dfs(parent, 0, hasApple, time, graph);

    return time;
}

private int dfs(int[] parent, int node, boolean[] hasApple, int time, Map<Integer, List<Integer>> graph) {
    // if the node is null or already visited, return 0
    if (parent[node] != -1) return 0;

    // initialize time for this node to 0
    time++;

    // iterate through the neighbors of the current node
    for (int neighbor : graph.getOrDefault(node, Collections.emptyList())) {
        // recursively calculate the minimum time required for the neighbor
        int neighborTime = dfs(parent, neighbor, hasApple, time, graph);

        // if the neighbor has an apple, add the time required to reach it and the neighbor itself
        if (hasApple[neighbor] || neighborTime > 0) {
            time++;
            // add the time required to reach the neighbor to the current node's time
            time += neighborTime;
        }
    }

    // return the time required to reach the current node from its parent
    return time - 1;
}
