public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    List<Character> asciiChars = new ArrayList<>();
    for (char c : s.toCharArray()) {
        asciiChars.add(c);
    }

    asciiChars.sort(Comparator.comparingInt(Character::codePointAt));

    StringBuilder sortedString = new StringBuilder();

    // Sort字符串
    while (!asciiChars.isEmpty()) {
        // Pick and add the smallest character not yet added
        int smallestIndex = findSmallestIndex(asciiChars);
        if (smallestIndex != -1) {
            sortedString.append(asciiChars.remove(smallestIndex));
        }

        // Pick and add the largest character not yet added
        int largestIndex = findLargestIndex(asciiChars);
        if (largestIndex != -1) {
            sortedString.append(asciiChars.remove(largestIndex));
        }
    }

    return sortedString.toString();
}

private int findSmallestIndex(List<Character> asciiChars) {
    int smallestIndex = -1;
    for (int i = asciiChars.size() - 1; i >= 0; i--) {
        if (!asciiChars.get(i).equals(sortedString.charAt(sortedString.length() - 1))) {
            smallestIndex = i;
            break;
        }
    }
    return smallestIndex;
}

private int findLargestIndex(List<Character> asciiChars) {
    int largestIndex = -1;
    for (int i = 0; i < asciiChars.size(); i++) {
        if (!asciiChars.get(i).equals(sortedString.charAt(sortedString.length() - 1))) {
            largestIndex = i;
            break;
        }
    }
    return largestIndex;
}
