public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n % 2 != 0) return false;

    int sum = 0;
    for (int x : nums) sum += x;
    int target = sum / 2;

    int[] dp = new int[target + 1];
    dp[0] = 1;

    for (int x : nums) {
        for (int i = target; i >= x; i--) {
            dp[i] += dp[i - x];
        }
    }

    return dp[target] > 0;
