import java.util.Arrays;

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }

    int totalSum = Arrays.stream(nums).sum();
    int targetSum = totalSum / nums.length;

    int maxLength = 0;
    Arrays.sort(nums);

    for (int i = 0; i < nums.length; i++) {
        maxLength += nums[i];
        if (maxLength < targetSum) {
            continue;
        }

        // Check if there exists a subarray that sums to targetSum
        if (subarraySum(nums, i, nums.length - 1, targetSum)) {
            return true;
        }
    }

    return false;
}

private boolean subarraySum(int[] nums, int start, int end, int targetSum) {
    int currentSum = nums[start];

    for (int i = start + 1; i <= end; i++) {
        currentSum += nums[i];
        if (currentSum == targetSum) {
            return true;
        }
        if (currentSum > targetSum) {
            break;
        }
    }

    return false;
}
