public class SubstringChecker {

    public static boolean hasAllCodes(String s, int k) {
        if (s == null || k <= 0) {
            throw new IllegalArgumentException("Invalid input");
        }

        int totalCodes = 1 << k;
        HashSet<String> seen = new HashSet<>();
        for (int i = 0; i <= s.length() - k; i++) {
            String code = s.substring(i, i + k);
            if (!seen.contains(code)) {
                seen.add(code);
                if (seen.size() == totalCodes) {
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        System.out.println(hasAllCodes("00110110", 2)); // Expected: true
        System.out.println(hasAllCodes("0110", 1));   // Expected: true
        System.out.println(hasAllCodes("0110", 2));   // Expected: false
    }
}
