public boolean hasAllCodes(String s, int k) {
    int totalCodes = (int) Math.pow(2, k);
    boolean[] seen = new boolean[totalCodes];

    int left = 0;
    int count = 0;

    for (int right = 0; right < s.length(); right++) {
        int mask = (1 << (k - 1)) - 1; // Mask the current character indices
        int code = (s.charAt(right) - '0') << (k - 1); // Left shift the mask
        if ((code & mask) == 0) {
            // Unmask the current character
            code = code >> (k - 1);
            if (seen[code]) {
                // If the code is already seen, return false
                return false;
            }
            seen[code] = true;
            count++;
        }

        // Remove the leftmost character of the current window
        if (right - left + 1 > k) {
            mask = (1 << (k - 1)) - 1; // Update the mask
            code = (s.charAt(left) - '0') << (k - 1); // Left shift the mask
            if ((code & mask) == 0) {
                // Remove the leftmost character of the current window
                code = code >> (k - 1);
                if (seen[code]) {
                    // If the code is already seen, return false
                    return false;
                }
                seen[code] = true;
                count--;
            }
            left++;
        }
    }

    return count == totalCodes;
}
