public int minInsertions(String s) {
    // Initialize variables to keep track of balance and insertions needed.
    int balance = 0; // Records the number of parentheses currently out of the correct order.
    int insertions = 0; // Counts the number of additional parentheses needed.

    // Iterate through each character in the string.
    for (char c : s.toCharArray()) {
        if (c == '(') {
            // Increment the balance for '('.
            balance++;
        } else {
            // If balance is negative, it means there's a missing right parenthesis.
            // We need to add an opening parenthesis to make them equal.
            // And, we increment the total number of insertions.
            if (balance < 0) {
                insertions++;
                balance++;
            }
            // Decrease the balance after seeing a matching right parenthesis.
            balance--;
        }
    }

    // If balance is still positive, it means there are extra opening parentheses.
    // We need to add that number of closing parentheses to balance the string.
    // And, we increment the total number of insertions.
    return insertions + balance;
}
