    while (len * fib[len - 1] < k) {
        int next = fib[len - 1] + fib[len - 2];
        fib[len++] = next;
    }

    int cnt = 0;
    for (int i = len - 1; i >= 0 && k > 0; i--) {
        while (k >= fib[i]) {
            k -= fib[i];
            cnt++;
        }
    }
    return cnt;
