    String numberStr = Integer.toString(num);
    for (int i = 1; i < numberStr.length(); i++) {
        int currentDigit = Character.digit(numberStr.charAt(i), 10);
        int previousDigit = Character.digit(numberStr.charAt(i - 1), 10);
        if (Math.abs(currentDigit - previousDigit) != 1) {
            return false;
        }
    }
    return true;
