public static List<Integer> findSteppingNumbers(int low, int high) {
    if (low >= high) return new ArrayList<>();

    List<Integer> Result = new ArrayList<>();

    Deque<Integer> queue = new ArrayDeque<>();
    queue.addAll(Arrays.asList(low));

    while (!queue.isEmpty()) {
        int num = queue.poll();

        if (num >= low && num <= high) {
            Result.add(num);
        }

        if (num % 10 <= 8 && num * 10 + (num % 10 + 1) <= high) {
            queue.add(num * 10 + (num % 10 + 1));
        }
        if (num % 10 >= 1 && num * 10 + (num % 10 - 1) <= high) {
            queue.add(num * 10 + (num % 10 - 1));
        }
    }

    Collections.sort(Result);

    return Result;
}
