    void generateSteppingNumbers(int min, int max, StringBuilder current, List<Integer> result) {
        for (int i = 0; i <= 9; i++) {
            if ((current.length() == 0 || i == Integer.parseInt(String.valueOf(current.charAt(current.length() - 1)))) {
                current.append(i);
                if (min <= Integer.parseInt(current.toString()) && Integer.parseInt(current.toString()) <= max) {
                    result.add(Integer.parseInt(current.toString()));
                }
                generateSteppingNumbers(min, max, current, result);
                current.setLength(current.length() - 1);
            }
        }
    }

    generateSteppingNumbers(String.valueOf(low), String.valueOf(high), new StringBuilder(), result);
    return result;
