import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new LinkedList<>();
    if (low == 0) {
        result.add(0);
    } else {
        for (int i = low === 1 ? 1 : 0; i <= 9; i++) {
            connected(result, i, low);
        }
    }
    return sorted(result, low, high);
}

private static void connected(List<Integer> result, int number, int low) {
    int lastDigit = lastDigit(number);
    int next = lastDigit + 1;
    int previous = lastDigit - 1;
    if (next <= 9) {
        result.add(number * 10 + next);
        connected(result, number * 10 + next, low);
    }
    if (previous >= 0) {
        result.add(number * 10 + previous);
        connected(result, number * 10 + previous, low);
    }
}

private static char lastDigit(int number) {
    return String.valueOf(number).charAt(String.valueOf(number).length() - 1);
}

private static List<Integer> sorted(List<Integer> result, int low, int high) {
    if (result.isEmpty()) {
        return result;
    }

    List<Integer> sortedList = new ArrayList<>(result);
    for (int i = 1; i < sortedList.size(); i++) {
        if (sortedList.get(i) < sortedList.get(i - 1)) {
            return sortedList;
        }
    }
    if (sortedList.get(sortedList.size() - 1) >= high) {
        return sortedList;
    }

    int nextIndex = sortedList.size();
    while (nextIndex < high) {
        int nextValue = findNext(sortedList, nextIndex);
        if (nextValue < high) {
            sortedList.add(nextValue);
        }
    }

    return sortedList;
}

private static int findNext(List<Integer> sortedList, int currentIndex) {
    int lastDigit = lastDigit(sortedList.get(currentIndex));
    if (lastDigit == 9) {
        return -1;
    }
    int next = lastDigit + 1;
    int nextValue = sortedList.get(currentIndex) * 10 + next;
    return nextValue;
}
