public class PowerOfTwoChecker {
    public static boolean isPowerOfTwo(int n) {
        // Handle edge cases for zero and negative numbers
        if (n <= 0) {
            return false;
        }
        // If n is 1, it's a power of two (2^0)
        if (n == 1) {
            return true;
        }
        // If n is even and greater than 1, check if it's a power of two
        // By repeatedly dividing n by 2 and checking if it becomes 1
        while (n > 1) {
            if (n % 2 != 0) {
                return false;
            }
            n /= 2;
        }
        return true;
    }

    public static void main(String[] args) {
        // Test cases to verify the correctness of the function
        System.out.println(isPowerOfTwo(1));  // true
        System.out.println(isPowerOfTwo(16)); // true
        System.out.println(isPowerOfTwo(3));  // false
        System.out.println(isPowerOfTwo(4));  // true
        System.out.println(isPowerOfTwo(5));  // false
    }
}
