import java.util.HashMap;
import java.util.Map;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int a : A) {
            freqMap.put(a, freqMap.getOrDefault(a, 0) + 1);
        }

        if (freqMap.containsValue(1)) {
            int freqForOne = freqMap.get(1);
            if (freqForOne > 1) {
                return 1;
            }
        }

        if (!freqMap.containsValue(2) || freqMap.get(2) % 2 != 0) {
            return 0;
        }

        Map<Integer, Integer>[] dp = new Map[2];
        dp[0] = new HashMap<>();
        dp[1] = new HashMap<>();
        dp[0].put(0, 1);

        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            int n = entry.getKey();
            int freq = entry.getValue();
            dp[(0 + 1) % 2].clear();
            for (Map.Entry<Integer, Integer> dpEntry : (0 + 1) % 2 == 1 ? dp[0] : dp[1].entrySet()) {
                int complement = n - dpEntry.getKey();
                if (complement >= 0 && dp[(0 + 1) % 2].containsKey(complement)) {
                    dp[(0 + 1) % 2].put(n, (dp[(0 + 1) % 2].getOrDefault(n, 0) * dpEntry.getValue()) % 1000000007);
                }
            }
            if (freq == 2) {
                dp[(0 + 1) % 2].put(n, (dp[(0 + 1) % 2].getOrDefault(n, 0) * freq) % 1000000007);
            } else if (freq > 2) {
                dp[(0 + 1) % 2].put(n, (dp[(0 + 1) % 2].getOrDefault(n, 0) * ((long)freq * ((freq-1)/2) % 1000000007) % 1000000007) % 1000000007);
            }
        }

        return dp[(0 + 1) % 2].getOrDefault(0, 0);
    }
}
