private static void squarePermutationsRec(int i, int[] A, boolean[] vis, int count) {
    if (i >= A.length) {
        count++;
        return;
    }
    for (int j = 0; j < A.length; j++) {
        if (!vis[j] && checkPerfectSquare(A[j], i)) {
            vis[j] = true;
            squarePermutationsRec(i + 1, A, vis, count);
            vis[j] = false;
        }
    }
}

private static boolean checkPerfectSquare(int n, int prevIndex) {
    int sum = prevIndex + n;
    return sum == sum * sum;
