import java.util.ArrayList;
import java.util.List;

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;

    List<List<Integer>> permutations = new ArrayList<>();

    // Generate all permutations
    permute(A, 0, n - 1, permutations);

    // Count valid permutations
    int count = 0;
    for (List<Integer> perm : permutations) {
        ifisValid(perm) {
            count++;
        }
    }

    return count;
}

private static void permute(int[] nums, int start, int end, List<List<Integer>> permutations) {
    if (start == end) {
        permutations.add(new ArrayList<>(List.of(nums)));
        return;
    }

    for (int i = start; i <= end; i++) {
        swap(nums, start, i);
        permute(nums, start + 1, end, permutations);
        swap(nums, start, i); // backtrack
    }
}

private static boolean isValid(List<Integer> perm) {
    for (int i = 0; i < perm.size() - 1; i++) {
        int sum = perm.get(i) + perm.get(i + 1);
        if (!isPerfectSquare(sum)) {
            return false;
        }
    }
    return true;
}

private static boolean isPerfectSquare(int num) {
