import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

public class SquarePermutations {

    public static int squarePermutations(int[] A) {
        if (A == null || A.length <= 1) return A == null ? 1 : 0;

        int n = A.length;
        Deque<Integer> queue = new ArrayDeque<>();
        for (int num : A) {
            if (num % 2 != 0) return 0;
            queue.offer((num - 1) / 2);
            queue.offer((num + 1) / 2);
        }

        int count = 0;
        Queue<Integer> seen = new ArrayDeque<>();
        seen.offer(0);

        while (!queue.isEmpty()) {
            int len = queue.size();
            count += len * 2;
            for (int i = 0; i < len; i++) {
                int num = queue.poll();
                Deque<Integer> newQueue = new ArrayDeque<>();
                if (seen.contains(num)) {
                    continue;
                }
                seen.offer(num);
                newQueue.offer(num * 2);
                newQueue.offer((num * 2) % 2 != 0 ? 5 - (num * 2) : (num * 2) - 1);
                queue.addAll(newQueue);
            }
        }

        return count;
    }
}
