public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty.");
    }

    int[] nextSmaller = new int[heights.length];
    int[] prevSmaller = new int[heights.length];

    highestNextSmaller(heights, nextSmaller);
    highestPreviousSmaller(heights, prevSmaller);

    int res = 0;
    final int n = heights.length;
    for (int i = 0; i < n; i++) {
        if (prevSmaller[i] == -1) {
            prevSmaller[i] = 0;
        }
        if (nextSmaller[i] == n) {
            nextSmaller[i] = n - 1;
        }
        res = Math.max(res, heights[i] * ((nextSmaller[i] - prevSmaller[i] - 1)));
    }
    return res;
}

private static void highestNextSmaller(int[] height, int[] res) {
    int stack[] = new int[height.length];
    int top = -1;
    for (int i = 0; i < height.length; i++) {
        while (top != -1 && height[stack[top]] >= height[i]) {
            res[stack[top]] = i;
            top--;
        }
        stack[++top] = i;
    }
    for (int i = 0; i < res.length; i++) {
        if (stack[i] >= 0) {
            res[i] = i - res[stack[i]];
        } else {
            res[i] = i - stack[i];
        }
    }
}

private static void highestPreviousSmaller(int[] height, int[] res) {
    int stack[] = new int[height.length];
    int top = -1;
    for (int i = height.length - 1; i >= 0; i--) {
        while (top != -1 && height[stack[top]] >= height[i]) {
            res[stack[top]] = i;
            top--;
        }
        stack[++top] = i;
    }
    for (int i = height.length - 1; i >= 0; i--) {
        if (stack[i] >= 0) {
            res[i] = res[stack[i]] - (height.length - 1 - i);
        } else {
            res[i] = height.length - 1 - i;
        }
    }
}
