public static int[] diagonalOrder(int[][] mat) {
    // Check if the input matrix is valid
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0;
    int col = 0;
    int direction = 1; // 1 for up, -1 for down

    for (int i = 0; i < m * n; i++) {
        result[i] = mat[row][col];

        // Calculate the next position based on the direction
        int nextRow = row + direction;
        int nextCol = col + (-direction);

        // Check if the next position is out of bounds
        if (isOutOfBounds(nextRow, nextCol, m, n)) {
            // Change direction
            direction *= -1;

            // Adjust the position if needed
            if (nextRow < 0) {
                nextRow = 0;
                if (direction == 1) {
                    col++;
                } else {
                    row++;
                }
            } else if (nextRow >= m) {
                nextRow = m - 1;
                if (direction == 1) {
                    col++;
                } else {
                    row--;
                }
            }
            if (nextCol < 0) {
                if (direction == 1) {
                    col = 0;
                } else {
                    row++;
                }
            } else if (nextCol >= n) {
                if (direction == 1) {
                    col++;
                } else {
                    row--;
                }
            }
        } else {
            row = nextRow;
            col = nextCol;
        }
    }

    return result;
}

private static boolean isOutOfBounds(int row, int col, int m, int n) {
    return row < 0 || row >= m || col < 0 || col >= n;
}
