public static int findSmallestInteger(int n) {
    // Convert the integer to an array of digits
    int[] digits = new int[String.valueOf(n).length()];
    for (int i = 0; i < digits.length; i++) {
        digits[i] = n % 10;
        n /= 10;
    }

    // Start from the largest possible prefix and check if it can be sorted
    for (int i = digits.length - 1; i > 0; i--) {
        if (digits[i] > digits[i - 1]) {
            // Find the smallest element in the suffix that is greater than the pivot
            for (int j = digits.length - 1; j > i - 1; j--) {
                if (digits[j] > digits[i - 1]) {
                    // Swap the pivot with the smallest element in the suffix
                    int temp = digits[i - 1];
                    digits[i - 1] = digits[j];
                    digits[j] = temp;
                    break; // No need to continue searching since the rest of the digits are in descending order
                }
            }

            // Sort the suffix in ascending order
            Arrays.sort(digits, i, digits.length);

            // Form the smallest integer from the digits
            int result = 0;
            for (int d : digits) {
                result = result * 10 + d;
            }

            return result;
        }
    }

    // If no valid permutation is found, return -1
    return -1;
}
