public class Solution {

    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }

        for (int i = 1; i < n; i++) {
            result.add(determineCenterSymmetric(i));
        }

        return result;
    }

    private static String determineCenterSymmetric(int n) {
        String left = leftSymmetric(n);
        String right = rightSymmetric(n);
        return left + right;
    }

    private static String leftSymmetric(int n) {
        if (n == 0) {
            return "0";
        }

        String leftPart = "";
        int half = n / 2;

        for (int i = 0; i < half; i++) {
            if (i == 0) {
                leftPart += "0";
            } else {
                leftPart += "3" + "5";
            }
        }

        return rightPart + leftPart;
    }

    private static String rightSymmetric(int n) {
        if (n == 0) {
            return "0";
        }

        String rightPart = "";
        int half = n / 2;

        for (int i = 0; i < half; i++) {
            if (i == 0) {
                rightPart += "0";
            } else {
                rightPart += "3" + "5";
            }
        }

        return rightPart;
    }
