public class LexicalOrder {

    /**
     * Returns all integers in the range [1, n] in lexicographical order.
     * 
     * @param n The upper limit of the range.
     * @return List of integers in lexicographical order.
     */
    public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            result.add(i);
        }
        result.sort(Integer::compareTo);
        return result;
    }

    public static void main(String[] args) {
        // Example usage
        List<Integer> result = lexicalOrder(13);
        System.out.println(result); // Output: [1,10,11,12,13,2,3,4,5,6,7,8,9]
    }
}
