public static void DFS(int current, int limit, int base, List<Integer> result) {
    if (result.size() >= limit) {
        return;
    }
    result.add(current);
    for (int i = 0; i < base; i++) {
        if (current * base + i <= limit) {
            DFS(current * base + i, limit, base, result);
        }
    }
