import java.lang.Math;

public class SquareSumSolver {
    public static int minPerfectSquareSum(int n) {
        // Check if the input is negative
        if (n < 0) {
            throw new IllegalArgumentException("Input must be non-negative");
        }

        // Base case: 0 can be achieved with 0 perfect squares
        if (n == 0) {
            return 0;
        }

        // Helper function to find the minimum number of perfect squares
        return findMinSquares(n);
    }

    private static int findMinSquares(int n) {
        // If n is a perfect square, return 1
        if (isPerfectSquare(n)) {
            return 1;
        }

        // Iterate from 1 to the square root of n
        for (int i = 1; i <= Math.sqrt(n); i++) {
            // Calculate the remaining sum after adding i^2
            int remaining = n - i*i;

            // Recursively find the minimum number of perfect squares for the剩余 sum
            int subProblem = findMinSquares(remaining);

            // Update the minimum number of perfect squares found
            minSquares = Math.min(minSquares, subProblem + 1);
        }

        return minSquares;
    }

    private static boolean isPerfectSquare(int num) {
        if (num < 0) {
            return false;
        }
        int root = (int) Math.sqrt(num);
        return root * root == num;
    }
}
