import java.util.HashMap;
import java.util.HashSet;

public class SquareSumCalculator {

    private final HashMap<Integer, Integer> memory;

    public SquareSumCalculator() {
        this.memory = new HashMap<>();
    }

    public static int minPerfectSquareSum(int n) {
        return findMinSquareSum(n);
    }

    private static int findMinSquareSum(int n) {
        if (n == 0) return 0;
        if (memory.containsKey(n)) return memory.get(n);

        int min = Integer.MAX_VALUE;
        for (int i = 1; i * i <= n; i++) {
            min = Math.min(min, 1 + findMinSquareSum(n - i * i));
        }

        memory.put(n, min);
        return min;
    }
}
