import java.lang.Math;

public class MinPerfectSquareSum {

    public static int minPerfectSquareSum(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("Input must be a positive integer.");
        }

        int dp[] = new int[n + 1];
       Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0; // Base case: 0 perfect squares sum up to 0

        // Iterate through each number from 1 to n
        for (int i = 1; i <= n; i++) {
            // Check all possible perfect squares less than i
            for (int j = 1; j * j <= i; j++) {
                int sum = j * j;
                dp[i] = Math.min(dp[i], dp[i - sum] + 1);
            }
        }

        return dp[n];
    }

    // Example usage
    public static void main(String[] args) {
        System.out.println(minPerfectSquareSum(12)); // Output: 3
        System.out.println(minPerfectSquareSum(13)); // Output: 2
    }
}
